update public.products set archived = true, visible = false, featured = false
  where sku in ('C001','C002','C003','C004','C005','C006','V001','V002','V003','V004','V005','D001','D002','D003','D004','O014','O002','O003','O004','B001','B002','B003','L001','L002','L003','A001','A002','A003');
